snippets.script:
function today() {
    var d = new Date();
    function p(n) { return (n < 10 ? "0" : "") + n; }
    return d.getFullYear() + "-" + p(d.getMonth() + 1) + "-" + p(d.getDate());
}
function now() {
    var d = new Date();
    function p(n) { return (n < 10 ? "0" : "") + n; }
    return today() + " " + p(d.getHours()) + ":" + p(d.getMinutes());
}
